      status_code: 200,
      agent: first.agent,
      data: first.candidate,
      model: first.model_used,
      verified: true,
      retries: 0,
      verdict: first.verdict_1,
    },
  }];
}

const retried = $('Parsear Reintento').first().json;
const ver2 = item;
const ok = Boolean(ver2.cumple) && retried.llm_ok;
return [{
